package android.view.inputmethod;import android.view.View;import android.widget.EditText;import android.text.Editable;import android.text.Spanned;import dev.mixer.android.ConcreteHostProbe;
public class BaseInputConnection implements InputConnection {
 private final EditText editor;private static final Object COMPOSING=new Object();public int mutations;public boolean closed;public BaseInputConnection(View target,boolean fullEditor){editor=target instanceof EditText value?value:null;}
 public static int getComposingSpanStart(CharSequence text){if(text instanceof Spanned spans)for(Object span:spans.getSpans(0,spans.length(),Object.class))if((spans.getSpanFlags(span)&Spanned.SPAN_COMPOSING)!=0)return spans.getSpanStart(span);return -1;}
 public static int getComposingSpanEnd(CharSequence text){if(text instanceof Spanned spans)for(Object span:spans.getSpans(0,spans.length(),Object.class))if((spans.getSpanFlags(span)&Spanned.SPAN_COMPOSING)!=0)return spans.getSpanEnd(span);return -1;}
 public static void removeComposingSpans(Editable text){for(Object span:text.getSpans(0,text.length(),Object.class))if((text.getSpanFlags(span)&Spanned.SPAN_COMPOSING)!=0)text.removeSpan(span);}
 private void enter(String name){ConcreteHostProbe.hit("BaseInputConnection."+name,"entry",this);mutations++;}private boolean done(String name,boolean value){ConcreteHostProbe.hit("BaseInputConnection."+name,"beforeReturn",this);return value;}
 private boolean insert(CharSequence text,boolean composing){if(closed||editor==null)return false;int start=getComposingSpanStart(editor.getText()),end=getComposingSpanEnd(editor.getText());if(start<0){start=Math.max(0,editor.getSelectionStart());end=Math.max(0,editor.getSelectionEnd());}int low=Math.min(start,end),high=Math.max(start,end);editor.hostReplace(low,high,text);removeComposingSpans(editor.getText());if(composing)editor.getText().setSpan(COMPOSING,low,low+text.length(),Spanned.SPAN_COMPOSING);return true;}
 @Override public boolean commitText(CharSequence text,int position){enter("commitText");return done("commitText",insert(text,false));}
 @Override public boolean setComposingText(CharSequence text,int position){enter("setComposingText");return done("setComposingText",insert(text,true));}
 @Override public boolean commitText(CharSequence text,int position,TextAttribute attributes){enter("commitTextWithAttributes");return done("commitTextWithAttributes",insert(text,false));}
 @Override public boolean setComposingText(CharSequence text,int position,TextAttribute attributes){enter("setComposingTextWithAttributes");return done("setComposingTextWithAttributes",insert(text,true));}
 @Override public boolean setComposingRegion(int start,int end){enter("setComposingRegion");if(editor==null||closed)return done("setComposingRegion",false);removeComposingSpans(editor.getText());editor.getText().setSpan(COMPOSING,start,end,Spanned.SPAN_COMPOSING);return done("setComposingRegion",true);}
 @Override public boolean setComposingRegion(int start,int end,TextAttribute attributes){return setComposingRegion(start,end);}
 @Override public boolean finishComposingText(){enter("finishComposingText");if(editor!=null)removeComposingSpans(editor.getText());return done("finishComposingText",!closed&&editor!=null);}
 @Override public boolean deleteSurroundingText(int before,int after){enter("deleteSurroundingText");if(editor==null||closed)return done("deleteSurroundingText",false);int start=Math.max(0,Math.min(editor.getSelectionStart(),editor.getSelectionEnd())-before),end=Math.min(editor.getText().length(),Math.max(editor.getSelectionStart(),editor.getSelectionEnd())+after);editor.hostReplace(start,end,"");return done("deleteSurroundingText",true);}
 @Override public boolean deleteSurroundingTextInCodePoints(int before,int after){enter("deleteSurroundingTextInCodePoints");if(editor==null||closed)return done("deleteSurroundingTextInCodePoints",false);String value=editor.getText().toString();int s=Math.max(0,Math.min(editor.getSelectionStart(),editor.getSelectionEnd())),e=Math.max(0,Math.max(editor.getSelectionStart(),editor.getSelectionEnd()));int start=value.offsetByCodePoints(s,-Math.min(before,value.codePointCount(0,s))),end=value.offsetByCodePoints(e,Math.min(after,value.codePointCount(e,value.length())));editor.hostReplace(start,end,"");return done("deleteSurroundingTextInCodePoints",true);}
 @Override public boolean setSelection(int start,int end){enter("setSelection");if(editor==null||closed)return done("setSelection",false);editor.setSelection(start,end);return done("setSelection",true);}
 @Override public boolean performEditorAction(int action){enter("performEditorAction");return done("performEditorAction",editor!=null&&!closed&&editor.hostEditorAction(action));}
 @Override public boolean sendKeyEvent(android.view.KeyEvent event){enter("sendKeyEvent");return done("sendKeyEvent",editor!=null&&!closed&&editor.dispatchKeyEvent(event));}
 @Override public boolean replaceText(int start,int end,CharSequence text,int position,TextAttribute attributes){enter("replaceText");return done("replaceText",editor!=null&&!closed&&editor.hostReplace(start,end,text));}
 @Override public boolean commitCompletion(CompletionInfo value){enter("commitCompletion");return done("commitCompletion",value!=null&&insert(value.getText(),false));}
@Override public boolean performPrivateCommand(String action,android.os.Bundle data){enter("performPrivateCommand");return done("performPrivateCommand",!closed);}
@Override public boolean setImeConsumesInput(boolean consumes){enter("setImeConsumesInput");return done("setImeConsumesInput",!closed);}
@Override public boolean previewHandwritingGesture(PreviewableHandwritingGesture gesture,android.os.CancellationSignal cancellation){enter("previewHandwritingGesture");return done("previewHandwritingGesture",!closed);}
@Override public boolean commitCorrection(CorrectionInfo value){enter("commitCorrection");return done("commitCorrection",!closed);}
@Override public boolean commitContent(InputContentInfo content,int flags,android.os.Bundle options){enter("commitContent");return done("commitContent",!closed);}
@Override public boolean beginBatchEdit(){enter("beginBatchEdit");return done("beginBatchEdit",!closed);}
@Override public boolean endBatchEdit(){enter("endBatchEdit");return done("endBatchEdit",!closed);}
@Override public boolean clearMetaKeyStates(int states){enter("clearMetaKeyStates");return done("clearMetaKeyStates",!closed);}
@Override public void performHandwritingGesture(HandwritingGesture gesture,java.util.concurrent.Executor executor,java.util.function.IntConsumer result){enter("performHandwritingGesture");if(executor!=null&&result!=null)executor.execute(()->result.accept(HANDWRITING_GESTURE_RESULT_UNSUPPORTED));ConcreteHostProbe.hit("BaseInputConnection.performHandwritingGesture","beforeReturn",this);}@Override public void closeConnection(){enter("closeConnection");closed=true;ConcreteHostProbe.hit("BaseInputConnection.closeConnection","beforeReturn",this);}}
